{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "A close butyl-linked arylpiperazine analogue with a CF3-substituted heteroaryl showed a brain:plasma ratio of 3.7 in rat and was explicitly labeled as good penetration, directly supporting CNS access for the query's butyl-piperazine-CF3-aryl motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "TFMPP, which contains the exact m-CF3-phenylpiperazine fragment, readily crosses the BBB with a Cmax brain-to-blood ratio greater than 10 in animals, supporting the CNS-penetrant nature of the query's arylpiperazine unit.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A PET radiotracer with the same butyl-piperazine and N-methyl uracil-like heterocycle penetrated the BBB in baboons with regional uptake matching 5-HT1A receptor distribution, demonstrating meaningful CNS access for the query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "FECUMI-101, a fluoroethyl analogue of the same chemotype, effectively crossed the BBB in baboon PET studies, confirming that this scaffold achieves adequate brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Trifluoperazine, a basic CF3-phenylpiperazine-containing CNS drug, crosses the BBB by passive diffusion with log BB 1.44, showing that the predicted ionization and efflux liabilities do not preclude high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A xanthine-containing analogue with an OCF3-phenyl substituent showed initial rat brain uptake of 0.51 %ID/g at 5 min, demonstrating that the xanthine core in the query is compatible with BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The highest-similarity analogue penetrated the BBB in baboon PET studies, and although it was not ideal as a 5-HT1A tracer due to low specific binding and fast clearance, it still provides direct evidence of meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple close analogues with the same arylpiperazine, butyl linker, and xanthine/triazolone-like heterocycle show direct brain penetration in rodents and primates; consistent in vivo CNS exposure evidence outweighs the physicochemical prior of low passive permeability and possible efflux.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux-transporter status of the query was not directly measured; P-gp liability is inferred from structure.",
    "Morgan similarities are moderate (0.27-0.38), so exact quantitative brain exposure may differ.",
    "No human CNS exposure data for the query or an exact analogue."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C10", "C08", "C04", "C09", "C05", "C07", "C11"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "arylpiperazine CNS penetration"
    }
  ],
  "revision_action": "initial"
}

